import mcphost

TABLE = "lc_run_events_02acf2a8"


def _extract(args):
    for key in ("body", "payload", "data"):
        v = args.get(key)
        if isinstance(v, dict):
            return v
    return args


def main(args):
    payload = _extract(args)

    try:
        mcphost.table.create(
            name=TABLE,
            columns={
                "run_id": "text",
                "chain": "text",
                "status": "text",
                "latency_ms": "real",
                "error": "text",
            },
        )
    except mcphost.table.TableError as e:
        if e.code != "table_already_exists":
            raise

    run_id = str(payload.get("run_id", "unknown"))
    chain = str(payload.get("chain", "unknown"))
    status = str(payload.get("status", "unknown"))
    latency_ms = payload.get("latency_ms")
    error = payload.get("error")

    mcphost.table.append(
        table=TABLE,
        rows=[{
            "run_id": run_id,
            "chain": chain,
            "status": status,
            "latency_ms": float(latency_ms) if isinstance(latency_ms, (int, float)) else None,
            "error": str(error) if error else None,
        }],
    )

    reacted = None
    if status == "error":
        ch = mcphost.channel.post(
            channel_id="lc_alerts_02acf2a8",
            body=f"[lc_run_reactor] chain={chain} run={run_id} FAILED: {error}",
        )
        reacted = "posted_alert"
    elif status == "completed":
        reacted = "logged_completion"
    else:
        reacted = "logged_event"

    return {
        "run_id": run_id,
        "chain": chain,
        "status": status,
        "reacted": reacted,
    }
